From bc221904a23a6f49edd46c77d262dfdd2213c168 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:05:53 +0100
Subject: [PATCH] gpu/nvidia: don't read an N/A target temperature as 0
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Some drivers report the GPU Target Temperature as N/A, which was read
as 0, so the maximum became only the shutdown margin (5 °C) and charts
with an automatic range drew 0 to 5 °C. Leave the maximum unset then.

BUG: 525406
---
 plugins/gpu/NvidiaSmiProcess.cpp | 7 ++++++-
 1 file changed, 6 insertions(+), 1 deletion(-)

diff --git a/plugins/gpu/NvidiaSmiProcess.cpp b/plugins/gpu/NvidiaSmiProcess.cpp
index 22b5122..18dc8f5 100644
--- a/plugins/gpu/NvidiaSmiProcess.cpp
+++ b/plugins/gpu/NvidiaSmiProcess.cpp
@@ -112,7 +112,12 @@ std::vector<NvidiaSmiProcess::GpuQueryResult> NvidiaSmiProcess::query()

         if (line.startsWith("        GPU Target Temperature") && tLimitTemp) {
             // GPU Shutdown Temp = GPU Target Temperature + tLimitShDn
-            data->maxTemperature = std::atoi(line.mid(line.indexOf(':') + 1)) + tLimitShDn;
+            // Some GPUs report the target temperature as N/A, keep the maximum unset then
+            bool ok = false;
+            const int targetTemperature = line.mid(line.indexOf(':') + 1).trimmed().split(' ').constFirst().toInt(&ok);
+            if (ok) {
+                data->maxTemperature = targetTemperature + tLimitShDn;
+            }
         }

         if (line.startsWith("        Graphics") && readMaxClocks) {
-- 
